import { execFile, spawn } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";
import type { AgentChangedFile } from "../types.ts";

const execFileAsync = promisify(execFile);

/** Fetch URL of the agent's checkout; pushing is disabled */
const UPSTREAM_URL = "https://github.com/microsoft/rnx-kit.git";

/** Files generated by `yarn install` that are not under `node_modules` */
const INSTALL_ARTIFACTS = [".yarn/install-state.gz", "rnx-kit-workspaces.json"];

const READY_MARKER = ".rnx-kit-evals.json";

/**
 * Root of everything the harness creates. Runs are scoped to this process so
 * that cleanup does not remove runs of a concurrent eval.
 */
export const HARNESS_ROOT = path.join(os.tmpdir(), "rnx-kit-evals");
export const RUNS_ROOT = path.join(HARNESS_ROOT, `runs-${process.pid}`);

/** Yarn cache shared by templates and runs */
export const YARN_CACHE = path.join(HARNESS_ROOT, "yarn-cache");

export type Run = {
  /** Directory containing the checkout, shims, logs and the agent's home */
  dir: string;
  /** The agent's checkout */
  workdir: string;
};

const templates = new Map<string, Promise<string[]>>();

function repositoryRoot(): string {
  return path.resolve(fileURLToPath(new URL("../../..", import.meta.url)));
}

async function git(cwd: string, args: string[]): Promise<string> {
  const { stdout } = await execFileAsync("git", args, {
    cwd,
    encoding: "utf8",
    maxBuffer: 1024 * 1024 * 1024,
  });
  return stdout;
}

function exec(command: string, args: string[], cwd: string, log: string) {
  const out = fs.openSync(log, "a");
  return new Promise<void>((resolve, reject) => {
    const child = spawn(command, args, {
      cwd,
      env: { ...process.env, YARN_CACHE_FOLDER: YARN_CACHE },
      stdio: ["ignore", out, out],
    });
    child.on("error", reject);
    child.on("close", (code) => {
      fs.closeSync(out);
      if (code === 0) {
        resolve();
      } else {
        reject(new Error(`'${command} ${args.join(" ")}' failed; see ${log}`));
      }
    });
  });
}

async function clone(ref: string, dest: string): Promise<void> {
  const root = repositoryRoot();
  try {
    await git(root, ["cat-file", "-e", `${ref}^{commit}`]);
  } catch (_) {
    throw new Error(
      `Commit ${ref} is not available; fetch it first, e.g. 'git fetch --depth=1 origin ${ref}'`
    );
  }

  // Unlike `git worktree`, a separate repository does not share config, refs
  // or hooks with the main checkout. Objects are borrowed through alternates,
  // like `git clone --shared`, which does not work with shallow clones.
  const commonDir = path.resolve(
    root,
    (await git(root, ["rev-parse", "--git-common-dir"])).trim()
  );
  await git(root, ["init", "--quiet", dest]);
  fs.writeFileSync(
    path.join(dest, ".git", "objects", "info", "alternates"),
    path.join(commonDir, "objects") + "\n"
  );
  const shallow = path.join(commonDir, "shallow");
  if (fs.existsSync(shallow)) {
    fs.copyFileSync(shallow, path.join(dest, ".git", "shallow"));
  }
  await git(dest, ["checkout", "--quiet", "--detach", ref]);
  await git(dest, ["remote", "add", "origin", UPSTREAM_URL]);
  await git(dest, ["remote", "set-url", "--push", "origin", "PUSH_DISABLED"]);
}

/**
 * Installs dependencies for `ref` once and returns the paths of everything
 * `yarn install` generated, relative to the template's root.
 */
function prepareTemplate(ref: string): Promise<string[]> {
  const pending = templates.get(ref);
  if (pending) {
    return pending;
  }

  const template = path.join(HARNESS_ROOT, "templates", ref);
  const marker = path.join(template, READY_MARKER);
  const result = (async () => {
    if (fs.existsSync(marker)) {
      return JSON.parse(fs.readFileSync(marker, "utf8")) as string[];
    }

    fs.rmSync(template, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(template), { recursive: true });
    await clone(ref, template);
    await exec("yarn", ["install"], template, `${template}.log`);

    // Ignored `node_modules` only; fixtures may check in `node_modules`
    const ignored = await git(template, [
      "ls-files",
      "--others",
      "--ignored",
      "--exclude-standard",
      "--directory",
    ]);
    const artifacts = ignored
      .split("\n")
      .map((p) => p.replace(/\/$/, ""))
      .filter(
        (p) =>
          path.posix.basename(p) === "node_modules" ||
          INSTALL_ARTIFACTS.includes(p)
      );
    fs.writeFileSync(marker, JSON.stringify(artifacts));
    return artifacts;
  })();

  templates.set(ref, result);
  result.catch(() => templates.delete(ref));
  return result;
}

/**
 * Creates an isolated checkout of `ref` with dependencies installed.
 */
export async function createRun(ref: string): Promise<Run> {
  const artifacts = await prepareTemplate(ref);
  const template = path.join(HARNESS_ROOT, "templates", ref);

  fs.mkdirSync(RUNS_ROOT, { recursive: true });
  // Resolve symlinks (e.g. `/var` -> `/private/var` on macOS) so that paths
  // match `process.cwd()` of commands run in the checkout
  const dir = fs.realpathSync(fs.mkdtempSync(path.join(RUNS_ROOT, "run-")));
  const workdir = path.join(dir, "repo");
  try {
    await clone(ref, workdir);
    await Promise.all(
      artifacts.map((p) => {
        const dest = path.join(workdir, p);
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        const log = path.join(dir, "cp.log");
        return exec("cp", ["-a", path.join(template, p), dest], dir, log);
      })
    );
  } catch (e) {
    removeRun(dir);
    throw e;
  }

  return { dir, workdir };
}

/**
 * Removes a run created by `createRun`. Other paths are ignored.
 */
export function removeRun(dir: string): void {
  const relative = path.relative(RUNS_ROOT, dir);
  if (relative.startsWith("run-") && !relative.includes(path.sep)) {
    fs.rmSync(dir, { recursive: true, force: true, maxRetries: 3 });
  }
}

/**
 * Removes all runs created by this process.
 */
export function removeAllRuns(): void {
  fs.rmSync(RUNS_ROOT, { recursive: true, force: true, maxRetries: 3 });
}

const STATUS: Record<string, AgentChangedFile["status"]> = {
  A: "added",
  C: "added",
  D: "deleted",
  M: "modified",
  R: "renamed",
  T: "modified",
};

/**
 * Returns the files changed relative to `ref`, including untracked files, and
 * the unified diff.
 */
export async function collectChanges(
  workdir: string,
  ref: string
): Promise<{ files: AgentChangedFile[]; diff: string }> {
  // Include untracked files in the diff
  await git(workdir, ["add", "--intent-to-add", "--all"]);

  const diffArgs = ["-c", "core.quotePath=false", "diff", "--find-renames"];
  const diff = await git(workdir, [...diffArgs, ref]);
  const nameStatus = await git(workdir, [
    ...diffArgs,
    "--name-status",
    "-z",
    ref,
  ]);

  const files: AgentChangedFile[] = [];
  const tokens = nameStatus.split("\0");
  for (let i = 0; i < tokens.length - 1; ) {
    const code = tokens[i][0];
    const isPair = code === "R" || code === "C";
    const file = tokens[i + (isPair ? 2 : 1)];
    i += isPair ? 3 : 2;

    const status = STATUS[code] ?? "modified";
    const change: AgentChangedFile = { path: file, status };
    if (status !== "deleted") {
      try {
        change.content = fs.readFileSync(path.join(workdir, file), "utf8");
      } catch (_) {
        // Not a regular file, e.g. a submodule
      }
    }
    files.push(change);
  }

  return { files, diff };
}
